INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000051',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about sports and fitness activities in Kannada","Use naanu X aaduttini/maaduttini for sports","Discuss favourite sports and teams"],"explanation":{"intro":"Sports and fitness vocabulary covers how to discuss sports, exercise, teams, and fitness activities in Kannada.","culturalNote":"Sports in Karnataka: cricket is the dominant sport — RCB (Royal Challengers Bengaluru/Bangalore — IPL team) is extremely popular. The team''s loyalty is fierce even though they struggled to win IPL titles for years (''ee sala cup namdhe'' — ''this year the cup is ours'' — became a cultural meme). Karnataka has produced great cricketers: Rahul Dravid (''The Wall'' — former India captain — born in Indore but grew up in Bengaluru — Karnataka cricket icon), Anil Kumble (former India captain — right-arm spinner — all-time great), Gundappa Viswanath (legendary batsman). Badminton: PV Sindhu (from Hyderabad but popularized across Karnataka). Football: Bengaluru FC (ISL — Indian Super League — very popular). Other sports: Kabaddi (Pro Kabaddi League — Bengaluru Bulls), athletics — PT Usha inspirational figure.  Traditional: kambala (water buffalo racing — Coastal Karnataka), malkhamb (pole gymnastics — North Karnataka), lagori (seven stones game)."},"examples":[{"sentence":"Naanu pratidinaa beLigge ooduttini haagu yoga maaduttini.","english":"Every morning I run and do yoga."},{"sentence":"Nimage RCB ishtavaagitta aa? Naakke thumba ishtavagutte!","english":"Do you like RCB? I really like them!"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about sports, fitness, and teams in Kannada."}}',
'{"items":[{"word":"aaDa","translation":"game/sport/match (general)","transliteration":"aaDa","pronunciation":"AA-Da","example":"channa aaDa"},{"word":"oodutte","translation":"running (I run — ooduttini)","transliteration":"ooduttini","pronunciation":"oo-DUT-ti-ni","example":"naanu ooduttini"},{"word":"yoga","translation":"yoga","transliteration":"yoga","pronunciation":"YO-ga","example":"yoga maaduttini"},{"word":"cricket","translation":"cricket","transliteration":"cricket","pronunciation":"KRIK-et","example":"cricket aaduttini"},{"word":"ball","translation":"ball","transliteration":"ball","pronunciation":"bol","example":"ball haakuttaane"},{"word":"team","translation":"team","transliteration":"team","pronunciation":"tiim","example":"nanna iShTa team"}]}',
'{"title":"Naanu X aaduttini — I play X (sports vocabulary in Kannada)","pattern":"Naanu X aaduttini = I play X (habitual). Naanu X maaduttini = I do X (for sports that use maadu — yoga maaduttini, exercise maaduttini). Favourite team: nanna iShTa team X (my favourite team is X). Watching sport: naanu X noduttini (I watch X). Stadium: stadium alli X match nodide (I watched the X match at the stadium).","explanation":"Sports vocabulary in Kannada: aaDa (game/match), aaDuttini (I play), ooduttini (I run — oodu = run), naaDuttini (I walk — naaDu = walk), hagaluttini (I swim — hagalu = swim), yoga maaduttini (I do yoga), gym ge hoguttini (I go to the gym). Winning: goolu haakuttaare (they score a goal — goolu = goal), hattu run maaduttaare (they make 10 runs), match gelluttaare (they win the match — gellu = win). Losing: match kaLedukontaare (they lose the match — kaledukonDu = losing). Favourite player: nanna iShTa player X (my favourite player is X). Result: X jaya aayitu (X won — jaya = victory).","examples":[{"sentence":"Ninne RCB vs MI match ide, naanu nanna geleya koodi stadium ge hode.","english":"Yesterday there was an RCB vs MI match, I went to the stadium with my friend."},{"sentence":"Naanu badminton haagu cricket aaDuttini — aadare naakke cricket hecchaagi ishtavagutte.","english":"I play badminton and cricket — but I like cricket more."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"ooduttini means?","options":["I run (habitual)","I walk","I swim","I play"],"correctAnswer":"I run (habitual)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Every morning I run and do yoga.","options":["Naanu pratidinaa beLigge ooduttini haagu yoga maaduttini.","Naanu pratidinaa raatri ooduttini haagu yoga maaduttini.","Naanu pratidinaa beLigge naaDuttini haagu yoga maaduttini.","Avanu pratidinaa beLigge ooduttaane haagu yoga maaduttaane."],"correctAnswer":"Naanu pratidinaa beLigge ooduttini haagu yoga maaduttini."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu badminton haagu cricket aaDuttini — aadare naakke cricket ___ ishtavagutte.","options":["hecchaagi","kammagi","ginta","samaana"],"correctAnswer":"hecchaagi"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Yesterday there was an RCB vs MI match, I went to the stadium with my friend.","wordBankItems":["Ninne","RCB","vs","MI","match","ide",",","naanu","nanna","geleya","koodi","stadium","ge","hode","."],"correctAnswer":"Ninne RCB vs MI match ide , naanu nanna geleya koodi stadium ge hode ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"aaDa means?","options":["game/sport/match (general)","run","exercise","ball"],"correctAnswer":"game/sport/match (general)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000052',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe a full daily schedule in Kannada","Use time expressions with gante for scheduling","Talk about fixed routines and weekly patterns"],"explanation":{"intro":"Daily schedule vocabulary covers how to describe a detailed timetable for a day, using time expressions, routine verbs, and schedule language in Kannada.","culturalNote":"Daily life patterns in Karnataka: typical Bengaluru professional''s day: 6-7 AM wake up, yoga/walk, 8-9 AM tiffin (idli/dosa/upma from home or nearby darshini — a standing quick-serve restaurant unique to Bengaluru), 9-10 AM commute to office (heavy traffic — 45-90 minutes!), 10 AM - 7 PM work (sometimes longer with meetings), 7-9 PM commute back, 9:30-10 PM dinner. Cultural note: Bengaluru darshini culture — these are stand-and-eat breakfast places, usually with a wide menu, reasonable price, very fast service. Famous ones: MTR (Mavalli Tiffin Rooms — established 1924 — famous for MTR dosa, rava idli invented here), Udupi hotels (serving all-day meals), Vidyarthi Bhavan (famous for dose — butter dose — since 1943). Late nights: IT professionals often work late and eat dinner around 10 PM. Weekend: usually relaxing on Saturday, family time on Sunday."},"examples":[{"sentence":"Pratidinaa naanu aaru gante ezhuttini, thambu naaDakke hoguttini, yenTu gante office ge hoguttini.","english":"Every day I get up at 6, then go for a walk, at 8 I go to the office."},{"sentence":"Raatri hattu gante naanu oota maadi, hadinomdu gante malagutte.","english":"At night I eat at 10, at 11 I sleep."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe a complete daily schedule with time expressions in Kannada."}}',
'{"items":[{"word":"ezhuttini","translation":"I get up/wake up (habitual)","transliteration":"ezhuttini","pronunciation":"e-ZHUT-ti-ni","example":"aaru gante ezhuttini"},{"word":"malagutte","translation":"I sleep (habitual — go to sleep)","transliteration":"malagutte","pronunciation":"ma-la-GUT-te","example":"hadinomdu gante malagutte"},{"word":"tayaaraguttini","translation":"I get ready (habitual)","transliteration":"tayaaraguttini","pronunciation":"ta-yaa-ra-GUT-ti-ni","example":"office ge tayaaraguttini"},{"word":"tiNDi tinuttini","translation":"I eat breakfast (habitual — tiNDi = tiffin/breakfast)","transliteration":"tiNDi tinuttini","pronunciation":"TIN-Di ti-NUT-ti-ni","example":"beLigge tiNDi tinuttini"},{"word":"maLage","translation":"sleep/rest (noun)","transliteration":"maLage","pronunciation":"ma-LA-ge","example":"channa maLage"},{"word":"schedule","translation":"schedule/timetable","transliteration":"schedule","pronunciation":"SKED-yool","example":"ee vaara schedule"}]}',
'{"title":"Nanna dinacharye — daily schedule in Kannada","pattern":"X gante Y maaduttini = at X o''clock I do Y. Nantara = after/then. Munde = before. Schedule: pratidinaa X gante ezhuttini, Y gante tiNDi tinuttini, Z gante office ge hoguttini. Asking about schedule: neevu yaavaga X maaduttiri? (when do you do X?). Free time: naakke bikkha time ide (I have free time — bikkha = free/empty).","explanation":"Daily schedule in Kannada: ezhuttini (I get up — from ezhuvudu = getting up), naaDuttini (I walk), tiNDi tinuttini (I eat breakfast — tiNDi = tiffin/breakfast), tayaaraguttini (I get ready), office ge hoguttini (I go to the office), kaela maaduttini (I work), oota tinnuttini (I eat dinner — oota = cooked food/meal), malagutte (I sleep). Time: beLigge (morning), madyaahna (afternoon), sanje (evening), raatri (night). Frequency: pratidinaa (every day), vaara vaara (every week), prativaara (every week), prati masaadi (every month). Weekly pattern: somavaara (Monday) to shani vaara (Saturday). Kannada time: Kannada uses 12-hour clock — beLigge (AM), raatri (PM). 12 gante = noon/midnight (context-specific).","examples":[{"sentence":"Nanna dinacharye: aaru gante ezhuttini, naaDakke hoguttini, yenTu gante office ge tayaaraguttini.","english":"My daily routine: I get up at 6, go for a walk, I get ready for the office at 8."},{"sentence":"Shani-Bhanu vaara nanna schedule bELe aguttade — late malagutte haagu late ezhuttini.","english":"My Saturday-Sunday schedule is different — I sleep late and wake up late."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"ezhuttini means?","options":["I get up/wake up (habitual)","I sleep","I get ready","I go"],"correctAnswer":"I get up/wake up (habitual)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Every day I get up at 6, then go for a walk, at 8 I go to the office.","options":["Pratidinaa naanu aaru gante ezhuttini, thambu naaDakke hoguttini, yenTu gante office ge hoguttini.","Pratidinaa naanu yenTu gante ezhuttini, thambu naaDakke hoguttini, aaru gante office ge hoguttini.","Pratidinaa avanu aaru gante ezhuttaane, thambu naaDakke hoguttaane, yenTu gante office ge hoguttaane.","Pratidinaa naanu aaru gante ezhuttini, thambu naaDakke hoguttini, hattu gante office ge hoguttini."],"correctAnswer":"Pratidinaa naanu aaru gante ezhuttini, thambu naaDakke hoguttini, yenTu gante office ge hoguttini."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Raatri hattu gante naanu oota maadi, hadinomdu gante ___ .","options":["malagutte","ezhuttini","hoguttini","bande"],"correctAnswer":"malagutte"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My daily routine: I get up at 6, go for a walk, get ready for office at 8.","wordBankItems":["Nanna","dinacharye",":","aaru","gante","ezhuttini",",","naaDakke","hoguttini",",","yenTu","gante","office","ge","tayaaraguttini","."],"correctAnswer":"Nanna dinacharye : aaru gante ezhuttini , naaDakke hoguttini , yenTu gante office ge tayaaraguttini ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"tiNDi means?","options":["breakfast/tiffin","lunch","dinner","snack"],"correctAnswer":"breakfast/tiffin"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000053',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss Karnataka''s historical sites in Kannada","Name major historical monuments and their significance","Use historical vocabulary in Kannada"],"explanation":{"intro":"Karnataka''s historical sites covers the major historical monuments, empires, and cultural heritage sites of the state with vocabulary to describe and discuss them.","culturalNote":"Karnataka''s rich history: Karnataka has been home to several powerful empires. (1) Chalukyas of Badami (6th-8th century CE) — cave temples at Badami (Aihole — cradle of temple architecture). (2) Rashtrakutas (8th-10th century CE) — rock-cut temples at Ellora (shared with Maharashtra). (3) Hoysala Empire (11th-14th century) — incredibly detailed star-shaped temples: Belur (Chennaigangeshwara), Halebid (Hoysaleshwara), Somnathpura — all UNESCO tentative list. (4) Vijayanagara Empire (14th-16th century) — Hampi (UNESCO World Heritage Site — the largest medieval Hindu city in the world — now a gorgeous ruin in Ballari/Hospet area). (5) Wodeyar Kingdom of Mysuru (16th century-1947) — Mysuru Palace (one of the most visited in India). (6) Tipu Sultan (18th century) — Srirangapatna (fort and tomb), Daria Daulat Bagh (summer palace). (7) Gol Gumbaz, Bijapur (now Vijayapura) — second largest dome in the world (Adil Shahi dynasty)."},"examples":[{"sentence":"Hampi UNESCO world heritage site — alli Vijayanagara samraajya kaala itihasa kandukobahud.","english":"Hampi is a UNESCO World Heritage Site — you can find the history of the Vijayanagara Empire era there."},{"sentence":"Hoysala devalayagaLu thumba prasiddha — Belur haagu Halebid alli channa kalaakoota ide.","english":"Hoysala temples are very famous — there is beautiful artistry in Belur and Halebidu."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can discuss Karnataka''s historical sites and heritage in Kannada."}}',
'{"items":[{"word":"itihasa","translation":"history","transliteration":"itihasa","pronunciation":"i-ti-HA-sa","example":"itihasa channa"},{"word":"samraajya","translation":"empire/kingdom","transliteration":"samraajya","pronunciation":"sam-RAAJ-ya","example":"Vijayanagara samraajya"},{"word":"devalaya","translation":"temple (formal/classical)","transliteration":"devalaya","pronunciation":"de-VA-la-ya","example":"Hoysala devalaya"},{"word":"kalaakoota","translation":"art form/artistic creation","transliteration":"kalaakoota","pronunciation":"ka-laa-KOO-ta","example":"channa kalaakoota"},{"word":"UNESCO","translation":"UNESCO World Heritage Site (UNESCO heritage site)","transliteration":"UNESCO","pronunciation":"yoo-NES-ko","example":"UNESCO site"},{"word":"kaala","translation":"era/period/time","transliteration":"kaala","pronunciation":"KAA-la","example":"hinde kaala"}]}',
'{"title":"Karnataka itihasa — history of Karnataka vocabulary","pattern":"X Y kaala inda bandide = X came from the Y era. X UNESCO site = X is a UNESCO site. X alli Y kaandubahud = in X you can find Y. X prasiddha yaakenendare Y = X is famous because Y. Historical timeline: munde (earlier/before), naantara (after), abhi (now).","explanation":"Historical vocabulary in Kannada: itihasa (history), samraajya (empire/dynasty), raaja (king), rani (queen), yuddha (war/battle), gedi (fort/fortress), devalaya/gudi (temple), mantapa (pillared hall), sthamba (pillar). Describing age: X saavira varsha hinde (X thousand years ago — hinde = ago/behind). Famous sites: Hampi (Vijayanagara ruins), Belur/Halebid (Hoysala temples), Badami (Chalukya caves), Gol Gumbaz Bijapur (dome), Srirangapatna (Tipu Sultan fort), Mysuru Palace (Wodeyar kingdom). Visiting: X noduvudu must aagutte (seeing X is a must — must = English borrowed). Learning: X bagge hecchaagi kaliyabeku (one should learn more about X).","examples":[{"sentence":"Srirangapatna alli Tipu Sultan itihasa kaanbahud — avara kaala thumba rakthapaathe aayitu.","english":"In Srirangapatna you can see Tipu Sultan''s history — his era was very turbulent."},{"sentence":"Naanu Hampi nodide adu naakke thumba adbhuta experience aayitu — UNESCO site nodida.","english":"I saw Hampi, it was a very amazing experience for me — I saw a UNESCO site."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"samraajya means?","options":["empire/kingdom","history","king","palace"],"correctAnswer":"empire/kingdom"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Hampi is a UNESCO World Heritage Site — you can find the history of the Vijayanagara Empire era there.","options":["Hampi UNESCO world heritage site — alli Vijayanagara samraajya kaala itihasa kandukobahud.","Belur UNESCO world heritage site — alli Vijayanagara samraajya kaala itihasa kandukobahud.","Hampi UNESCO world heritage site — alli Hoysala samraajya kaala itihasa kandukobahud.","Hampi UNESCO world heritage site — alli Vijayanagara samraajya kaala kalaakoota kandukobahud."],"correctAnswer":"Hampi UNESCO world heritage site — alli Vijayanagara samraajya kaala itihasa kandukobahud."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Hoysala ___ thumba prasiddha — Belur haagu Halebid alli channa kalaakoota ide.","options":["devalayagaLu","samraajyagaLu","kaalagaLu","itihasagaLu"],"correctAnswer":"devalayagaLu"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I saw Hampi, it was a very amazing experience for me — I saw a UNESCO site.","wordBankItems":["Naanu","Hampi","nodide","adu","naakke","thumba","adbhuta","experience","aayitu","—","UNESCO","site","nodida","."],"correctAnswer":"Naanu Hampi nodide adu naakke thumba adbhuta experience aayitu — UNESCO site nodida ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"itihasa means?","options":["history","heritage","culture","tradition"],"correctAnswer":"history"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000054',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss social media and technology in Kannada","Use naanu X post maadide for social media actions","Talk about apps, internet, and digital life"],"explanation":{"intro":"Social media and technology vocabulary covers how to discuss apps, digital activities, online communication, and the internet in Kannada.","culturalNote":"Technology culture in Karnataka: Bengaluru is India''s technology capital — the startup ecosystem, the IT offices, and a highly educated young population make technology central to life. Social media: Instagram (very popular among young Kannadigas — called ''Insta'' informally), Twitter/X, Facebook (used by older generations), YouTube (''YouTubealli nodi'' — very common phrase), LinkedIn (professional networking). Local tech: Flipkart (Bengaluru''s e-commerce giant — founded by IIT alumni), Amazon India (large office in Bengaluru), Infosys/Wipro/TCS (IT giants). Apps: Namma Metro app (Bengaluru metro), BMTC app (Bengaluru buses), Zomato (founded in Delhi but huge Bengaluru operations), Swiggy (founded in Bengaluru). Language tech: Google Translate (now supports Kannada well — decent but not perfect). AI/ML: Bengaluru is India''s center for AI research. Digital payment: GPay (Google Pay), PhonePe, Paytm — all widely used. Selfie culture: ''selfie'' is used directly in Kannada conversation!"},"examples":[{"sentence":"Naanu Instagram alli Hampi naanna chitra post maadide, thumba likes bande!","english":"I posted my Hampi photo on Instagram, many likes came!"},{"sentence":"Naakke new app download maadabeku — Bengaluru traffic live nodes.","english":"I need to download a new app — it shows Bengaluru traffic live."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can discuss social media, technology, and digital life in Kannada."}}',
'{"items":[{"word":"chitra","translation":"photo/picture","transliteration":"chitra","pronunciation":"CHIT-ra","example":"chitra post maadu"},{"word":"post maadu","translation":"post (on social media)","transliteration":"post maadu","pronunciation":"pOst MAA-du","example":"Instagram alli post maadu"},{"word":"like","translation":"like (social media like)","transliteration":"like","pronunciation":"laik","example":"thumba likes bande"},{"word":"download","translation":"download","transliteration":"download","pronunciation":"DOWN-lod","example":"app download maadu"},{"word":"internet","translation":"internet","transliteration":"internet","pronunciation":"IN-tar-net","example":"internet illa"},{"word":"app","translation":"app (mobile application)","transliteration":"app","pronunciation":"aep","example":"new app"}]}',
'{"title":"Social media haagu technology — vocabulary in Kannada","pattern":"X alli post maadide = I posted on X. X ge photo haakide = I took a photo of X. Download maadabeku = need to download. Instagram/WhatsApp/Facebook/YouTube — all proper nouns used directly. App install maadu = install an app. Battery charge maadu = charge the battery. Data illa = no data (no internet).","explanation":"Technology vocabulary in Kannada: chitra (photo/picture), video (video), post (post), share (share), like (like), comment (comment), follow (follow). Actions: post maadu (post), share maadu (share), download maadu (download), upload maadu (upload), install maadu (install). Internet: wifi (wifi), data (mobile data), hotspot (hotspot). Problems: app crash aayitu (app crashed), internet naaDuttilla (internet is not working — naaDuttilla = not running), battery hoguttide (battery is draining). Online shopping: online kharchu maaduttini (I shop online). Video call: zoom call ide (there is a zoom call). Meme: meme share maadide (I shared a meme).","examples":[{"sentence":"YouTube alli Yakshagana video nodide — thumba channa itu, share maadide.","english":"I watched a Yakshagana video on YouTube — it was very good, I shared it."},{"sentence":"Nanna WiFi naaDuttilla, data tEgeyuttiddeeni — eshtu time aagutte?","english":"My WiFi is not working, I am using data — how much time will this take?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"chitra means?","options":["photo/picture","video","post","story"],"correctAnswer":"photo/picture"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I posted my Hampi photo on Instagram, many likes came!","options":["Naanu Instagram alli Hampi naanna chitra post maadide, thumba likes bande!","Naanu YouTube alli Hampi naanna chitra post maadide, thumba likes bande!","Naanu Instagram alli Mysuru naanna chitra post maadide, thumba likes bande!","Naanu Instagram alli Hampi naanna video post maadide, thumba likes bande!"],"correctAnswer":"Naanu Instagram alli Hampi naanna chitra post maadide, thumba likes bande!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nanna WiFi naaDuttilla, ___ tEgeyuttiddeeni — eshtu time aagutte?","options":["data","app","battery","internet"],"correctAnswer":"data"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I watched a Yakshagana video on YouTube — it was very good, I shared it.","wordBankItems":["YouTube","alli","Yakshagana","video","nodide","—","thumba","channa","itu",",","share","maadide","."],"correctAnswer":"YouTube alli Yakshagana video nodide — thumba channa itu , share maadide ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"post maadu means?","options":["post (on social media)","send a letter","put something","write"],"correctAnswer":"post (on social media)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000055',1,'APPROVED','PUBLISHED',
'{"objectives":["Use extended meeting and greeting phrases in Kannada","Introduce yourself and others in social situations","Use small talk vocabulary to break the ice"],"explanation":{"intro":"Extended meeting and greeting phrases covers a deeper set of social phrases for introductions, small talk, asking how someone is doing, and wrapping up a conversation in Kannada.","culturalNote":"Social greetings in Karnataka: Namaskara is the universal greeting — acceptable in all communities and contexts. It can be said with hands folded (anjali mudra). Beyond Namaskara: each community has specific greetings. Lingayat: ''Omm Namah Shivaya''. Vaishnava Brahmin: ''Hare Krishana''. Muslim: ''Salaam Alaikum'' (responded: ''Waalaikum Salaam''). Christian: ''God bless you''. Modern/urban: ''Hi/Hello'' (English) mixed freely. Asking how someone is: hege iddiri? (formal — how are you?), henge (informal — how are you?). Standard response: channaagi iddini (I am fine/well — channaagi = well/finely). Returning question: neevu henge? (how about you? — informal). Small talk topics: traffic, weather, food, cricket — guaranteed to start a conversation with any Kannadiga. Parting: hoguttini (I am going), banni (please come — invitation), mattaadi banni (please come talk again), nodu kottu (see you later — give a look/glance)."},"examples":[{"sentence":"Namaskara! Hege iddiri? Naanu channaagi iddini. Neevu?","english":"Hello! How are you? I am fine. And you?"},{"sentence":"Thumba dina aayitu, neevu hege iddiri? Kaela hege naaduttide?","english":"It''s been a long time, how are you? How is work going?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can hold extended greetings and small talk in Kannada with confidence."}}',
'{"items":[{"word":"channaagi iddini","translation":"I am fine/well (response to how are you)","transliteration":"channaagi iddini","pronunciation":"chan-NAA-gi ID-di-ni","example":"channaagi iddini, dhanyavadagalu"},{"word":"thumba dina","translation":"long time (lit. many days)","transliteration":"thumba dina","pronunciation":"THUM-ba DI-na","example":"thumba dina aayitu"},{"word":"naaduttide","translation":"is going/is running (how is it going)","transliteration":"naaduttide","pronunciation":"NAA-dut-ti-de","example":"kaela hege naaduttide?"},{"word":"mattaadi banni","translation":"come talk again/let''s talk again (farewell)","transliteration":"mattaadi banni","pronunciation":"mat-TAA-di BAN-ni","example":"mattaadi banni"},{"word":"nodu kottu","translation":"see you later/give a look (informal farewell)","transliteration":"nodu kottu","pronunciation":"NO-du KOT-tu","example":"nodu kottu"},{"word":"aagali","translation":"it''s okay/that''s fine/let it be","transliteration":"aagali","pronunciation":"AA-ga-li","example":"aagali, problem illa"}]}',
'{"title":"Namaskara! Hege iddiri? — extended greeting phrases in Kannada","pattern":"Namaskara! = Hello! Hege iddiri? = How are you? (formal). Channaagi iddini = I am fine/well. Neevu henge? = And you? (informal). Thumba dina aayitu = it''s been a long time. Mattaadi banni = please come talk again. Nodu kottu = see you later (informal). Aagali = it''s okay / that''s fine.","explanation":"Extended greetings in Kannada: (1) Meeting: Namaskara! Hege iddiri? Channaagi iddiri aa? (2) Asking about activities: X hege naaduttide? (how is X going? — X = kaela/health/family). (3) Long time: thumba dinaaythu nimage nodilla (it''s been a long time since I saw you). (4) Response to ''how are you'': channaagi iddini (I am fine), saadharaNavaagithe (it''s ordinary/so-so — saadharana = ordinary), thumba dodam ide (lots of trouble — dodam = difficulty/trouble), oLLeyade (it''s okay). (5) Farewell: hoguttini, mattaadi baruttini (I''m going, I''ll come again), nodu kottu (see you later), take care (English phrase used).","examples":[{"sentence":"Thumba dina aayitu nimage nodilla — kaela hege naaduttide, family channaagi iddaare aa?","english":"It''s been a long time since I saw you — how is work going, is the family doing well?"},{"sentence":"Hoguttini, mattaadi banni — ee vaara banni namma manege oota tinnoke.","english":"I''m leaving, please come again — come this week to eat at our house."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"channaagi iddini means?","options":["I am fine/well","I am not well","I am tired","I am happy"],"correctAnswer":"I am fine/well"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Hello! How are you? I am fine. And you?","options":["Namaskara! Hege iddiri? Naanu channaagi iddini. Neevu?","Namaskara! Hege iddiri? Avaru channaagi iddaare. Neevu?","Namaskara! Hege iddiri? Naanu channaagi iddini. Avaru?","Namaskara! Hege ittiri? Naanu channaagi iddini. Neevu?"],"correctAnswer":"Namaskara! Hege iddiri? Naanu channaagi iddini. Neevu?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Thumba dina aayitu nimage nodilla — kaela hege naaduttide, family channaagi ___ aa?","options":["iddaare","iddiri","iddini","iddaane"],"correctAnswer":"iddaare"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I''m leaving, please come again — come this week to eat at our house.","wordBankItems":["Hoguttini",",","mattaadi","banni","—","ee","vaara","banni","namma","manege","oota","tinnoke","."],"correctAnswer":"Hoguttini , mattaadi banni — ee vaara banni namma manege oota tinnoke ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"aagali means?","options":["it''s okay/that''s fine","come here","wait","go ahead"],"correctAnswer":"it''s okay/that''s fine"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000056',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss current events and news in Kannada","Use sambhava and news vocabulary","Express opinions about events in simple Kannada"],"explanation":{"intro":"Current events vocabulary covers how to discuss news, current affairs, social topics, and express simple opinions about recent happenings in Kannada.","culturalNote":"News culture in Karnataka: print newspapers: Prajavani (leading Kannada daily), Vijaya Karnataka (Kannada daily — Bengaluru-based), Deccan Herald (English — Bengaluru-based), Times of India (national but large Karnataka readership). TV news: TV9 Kannada, Star Suvarna, ETV Kannada. Online news: Vijaya Karnataka online, OnIndia Kannada. Radio: Radio Indigo, Big FM, Radio City (Bengaluru-based stations). Important news topics in Karnataka: water dispute (Cauvery water issue between Karnataka and Tamil Nadu — very politically sensitive), North-South Karnataka development gap (a persistent political issue), Bengaluru infrastructure (metro expansion, traffic, flooding in low-lying areas during monsoon), IT sector news, startup funding (funding roundups reported in local news), political developments (Karnataka assembly elections every 5 years — BJP vs Congress vs JD(S) main parties)."},"examples":[{"sentence":"Inja Prajavani alli thumba muhtvada samachar itu — Bengaluru ge nadiyanneeru sakktu siguttade anta.","english":"Today in Prajavani there was very important news — apparently Bengaluru will get river water sufficiently."},{"sentence":"Naakke ee samachar nambuka aguttilla — neevu nodidiri aa?","english":"I can''t believe this news — did you see it?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can discuss news and current events in basic Kannada."}}',
'{"items":[{"word":"samachar","translation":"news/information","transliteration":"samachar","pronunciation":"sa-ma-CHAR","example":"samachar keLide"},{"word":"sambhava","translation":"event/happening/incident","transliteration":"sambhava","pronunciation":"SAM-bha-va","example":"ee sambhava"},{"word":"muhtvada","translation":"important/significant","transliteration":"muhtvada","pronunciation":"muht-VA-da","example":"muhtvada vishaya"},{"word":"nambuka","translation":"belief/trust (nambuka aguttilla = can''t believe)","transliteration":"nambuka","pronunciation":"NAM-bu-ka","example":"nambuka aguttilla"},{"word":"sarkaara","translation":"government","transliteration":"sarkaara","pronunciation":"sar-KAA-ra","example":"sarkaara niirdhara"},{"word":"niirdhara","translation":"decision/resolution","transliteration":"niirdhara","pronunciation":"NEER-dha-ra","example":"channa niirdhara"}]}',
'{"title":"Samachar haagu sambhava — news vocabulary in Kannada","pattern":"Inja X alli Y samachar itu = today there was Y news in X (media outlet). Samachar keLide = I heard news. Muhtvada samachar = important news. Nambuka aguttilla = I can''t believe it. Sarkaara Y maadide = the government did Y. Opinion: ee sambhava bagge naanna abipraaya X (my opinion about this event is X).","explanation":"News vocabulary in Kannada: samachar (news — from Sanskrit sambhava/samaachar), sambhava (event/happening), niirdhara (decision), niiyama (rule/law — niiyama maaduttaare = they make a rule). Government: sarkaara (government), mantri (minister), mukhyamantri (chief minister), pradhaan mantri (Prime Minister). Election: chunaave (election), vote (vote), gellida (won — gellida party = winning party). Local issues: neeru (water — Bengaluru water scarcity), traffic (traffic), metro (metro — namma metro expansion). Expressing concern: ee bhaari anuchita (this is quite unjust — anuchita = unjust). Expressing support: ee niirdhara oLLeyade (this decision is good).","examples":[{"sentence":"Namma metro inda airport ge hogutte anta samachar bande — naakke thumba santosha aayitu.","english":"News came that the metro will go to the airport — I was very happy about it."},{"sentence":"Cauvery neeru sarkaara niirdhara bagge namma ooru alli thumba charchey naaduttide.","english":"There is a lot of discussion happening in our town about the government''s decision on Cauvery water."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"samachar means?","options":["news/information","event","decision","politics"],"correctAnswer":"news/information"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Today in Prajavani there was very important news — apparently Bengaluru will get river water sufficiently.","options":["Inja Prajavani alli thumba muhtvada samachar itu — Bengaluru ge nadiyanneeru sakktu siguttade anta.","Ninne Prajavani alli thumba muhtvada samachar itu — Bengaluru ge nadiyanneeru sakktu siguttade anta.","Inja Vijaya Karnataka alli thumba muhtvada samachar itu — Bengaluru ge nadiyanneeru sakktu siguttade anta.","Inja Prajavani alli thakku muhtvada samachar itu — Bengaluru ge nadiyanneeru sakktu siguttade anta."],"correctAnswer":"Inja Prajavani alli thumba muhtvada samachar itu — Bengaluru ge nadiyanneeru sakktu siguttade anta."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Namma metro inda airport ge hogutte anta samachar bande — naakke thumba ___ aayitu.","options":["santosha","chintana","dukha","aashcharya"],"correctAnswer":"santosha"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: There is a lot of discussion happening in our town about the Cauvery water decision.","wordBankItems":["Cauvery","neeru","sarkaara","niirdhara","bagge","namma","ooru","alli","thumba","charchey","naaduttide","."],"correctAnswer":"Cauvery neeru sarkaara niirdhara bagge namma ooru alli thumba charchey naaduttide ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"sarkaara means?","options":["government","minister","election","decision"],"correctAnswer":"government"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000057',1,'APPROVED','PUBLISHED',
'{"objectives":["Ask for and offer help in Kannada","Use dayavittu sahaya kodi for requesting help","Offer help with naanu sahaaya maaduttini"],"explanation":{"intro":"Asking for help and assistance covers how to request help, offer assistance, and respond to requests in various situations in Kannada.","culturalNote":"Help and assistance culture in Karnataka: community help (ooru oLLeyadu = village solidarity — helping neighbors) is a strong tradition. Helping a stranger on the road is generally appreciated and expected. Urban helping: in Bengaluru, asking a stranger for directions is completely normal — most will help. Auto driver help: auto drivers are knowledgeable about local routes and can be relied upon for neighborhood-level directions. Emergency help: 112 is India''s national emergency number (police/ambulance). Karnataka-specific: 100 (police), 101 (fire), 108 (ambulance — a dedicated ambulance service very well-regarded in Karnataka). Senior citizens: helping elderly people is a cultural value. Strangers: strangers will often voluntarily help tourists, especially around religious places. Mutual help groups: mahila sangha (women''s self-help groups), youth organizations — community support structures in Karnataka."},"examples":[{"sentence":"Dayavittu naakke sahaaya maadi — ee bari hege maadabeku anta gottilla.","english":"Please help me — I don''t know how to do this work."},{"sentence":"Naanu nimage sahaaya maaduttini, dayavittu heLi — enu beku?","english":"I will help you, please tell me — what do you need?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can ask for and offer help in Kannada in everyday situations."}}',
'{"items":[{"word":"sahaaya","translation":"help/assistance","transliteration":"sahaaya","pronunciation":"sa-HAA-ya","example":"sahaaya beku"},{"word":"sahaaya maadi","translation":"please help (request)","transliteration":"sahaaya maadi","pronunciation":"sa-HAA-ya MAA-di","example":"dayavittu sahaaya maadi"},{"word":"sahaaya maaduttini","translation":"I will help (offer)","transliteration":"sahaaya maaduttini","pronunciation":"sa-HAA-ya MAA-dut-ti-ni","example":"naanu sahaaya maaduttini"},{"word":"gottilla","translation":"I don''t know (gottilla = not known — impersonal)","transliteration":"gottilla","pronunciation":"GOT-til-la","example":"naakke gottilla"},{"word":"kashtavagutte","translation":"it is difficult/hard","transliteration":"kashtavagutte","pronunciation":"KASH-ta-va-gut-te","example":"naakke kashtavagutte"},{"word":"possible","translation":"possible (possible aa? = is it possible?)","transliteration":"possible","pronunciation":"POS-si-bul","example":"ee possible aa?"}]}',
'{"title":"Dayavittu sahaaya maadi — asking for help in Kannada","pattern":"Dayavittu sahaaya maadi = please help me (dayavittu = please, sahaaya = help, maadi = do). Naakke sahaaya beku = I need help. Naanu sahaaya maaduttini = I will help (offer). Enu gottilla = I don''t know anything about it. Enu maadabeku? = what should be done? / what do I do? (asking for guidance). Possible aa? = is it possible? (asking feasibility).","explanation":"Help vocabulary in Kannada: sahaaya (help/assistance), sahaaya maadi (help me — informal request), sahaaya maadiri (help me please — slightly more polite), dayavittu sahaaya maadiri (please help me — most polite). Offering help: naanu nimage sahaaya maaduttini (I will help you), naakke sahaaya maadabeku anta ide aa? (should I help you? — checking). Declining help: thank you, naakke sahaaya beda (thank you, I don''t need help). Asking what is needed: enu sahaaya beku? (what help is needed?). Expressing difficulty: naakke ee vishaya kashtavagutte (this subject is difficult for me). Not knowing: naakke gottilla (I don''t know — gottilla = not known). Emergency: help beku! ambulance call maadi! (need help! call ambulance!).","examples":[{"sentence":"Excuse me, ee form hege fill maadabeku anta gottilla — neevu sahaaya maaduttiri aa?","english":"Excuse me, I don''t know how to fill this form — will you help me?"},{"sentence":"Aree nodi, avara luggage thumba heavy ide — naavu koodi nooDubidu, sahaaya maadona.","english":"Oh look, their luggage is very heavy — let''s help together, let''s assist."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"sahaaya means?","options":["help/assistance","work","service","support"],"correctAnswer":"help/assistance"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Please help me — I don''t know how to do this work.","options":["Dayavittu naakke sahaaya maadi — ee bari hege maadabeku anta gottilla.","Dayavittu nimge sahaaya maadi — ee bari hege maadabeku anta gottilla.","Dayavittu naakke sahaaya kodi — ee bari hege maadabeku anta gottilla.","Aagali naakke sahaaya maadi — ee bari hege maadabeku anta gottilla."],"correctAnswer":"Dayavittu naakke sahaaya maadi — ee bari hege maadabeku anta gottilla."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Excuse me, ee form hege fill maadabeku anta ___ — neevu sahaaya maaduttiri aa?","options":["gottilla","kashtavagutte","possible alla","maadabeku"],"correctAnswer":"gottilla"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I will help you, please tell me — what do you need?","wordBankItems":["Naanu","nimage","sahaaya","maaduttini",",","dayavittu","heLi","—","enu","beku","?"],"correctAnswer":"Naanu nimage sahaaya maaduttini , dayavittu heLi — enu beku ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"gottilla means?","options":["I don''t know (impersonal — not known)","I can''t do","I don''t have","I don''t want"],"correctAnswer":"I don''t know (impersonal — not known)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000058',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe plans for a celebration in Kannada","Use habba vocabulary for festival planning","Talk about preparing for birthdays and special events"],"explanation":{"intro":"Planning a celebration covers how to describe preparing for a festival, birthday, or special event — from inviting people to making arrangements — in Kannada.","culturalNote":"Celebration culture in Karnataka: celebrations are elaborate and inclusive in Karnataka. (1) Birthday (birthday / huttida habba / huttida naaLu — birthday = lit. born festival). Traditions: birthday person gets ''blessed'' by elders, cake is cut (cake is fully embraced in modern Karnataka birthdays), family outing to a restaurant, or home celebration with sweets. Gift: birthday gift (present). Surprise party: surprise party (English term used). Singing: ''Happy Birthday to You'' is sung everywhere (in English). (2) Ugaadi (Kannada New Year): family gathering, holige/obbattu made at home, bevu-bella (neem+jaggery mix — eaten at start of new year symbolizing life''s bitterness and sweetness). (3) Ganesh Chaturthi: 10-day festival celebrated across Karnataka — Gauri Ganesh habba preparations start weeks before. (4) Sankranti (January 14): sesame sweets (ellu bella), flying kites, family gatherings. (5) Diwali: fire crackers (pataki), sweets (mithai)."},"examples":[{"sentence":"Naanna birthday naale ide, naanu nanna mitrara nimantrana kodi friends ge biTTiddeeni.","english":"My birthday is tomorrow, I have already given invitations to my friends."},{"sentence":"Ugaadi habbaake naanu obbattu maadabeku — amma naakke recipe heLidaaLe.","english":"For Ugaadi festival I need to make obbattu — mother has told me the recipe."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can plan and describe a celebration or festival in Kannada."}}',
'{"items":[{"word":"huttida naaLu","translation":"birthday (lit. born day)","transliteration":"huttida naaLu","pronunciation":"HUT-ti-da NAA-Lu","example":"huttida naaLu habba"},{"word":"samaaraambha","translation":"celebration/event/function","transliteration":"samaaraambha","pronunciation":"sa-maa-RAAM-bha","example":"channa samaaraambha"},{"word":"tailaari","translation":"preparation/readying","transliteration":"tailaari","pronunciation":"tai-LAA-ri","example":"tailaari maaduttiddeeni"},{"word":"amantraNe","translation":"to invite/invitation act","transliteration":"amantraNe","pronunciation":"a-MAN-tra-Ne","example":"amantraNe kodi"},{"word":"recipe","translation":"recipe","transliteration":"recipe","pronunciation":"RE-si-pi","example":"recipe heLi"},{"word":"biTTiddeeni","translation":"have already (done — used with action)","transliteration":"biTTiddeeni","pronunciation":"biT-TID-dee-ni","example":"maadabiTTiddeeni"}]}',
'{"title":"Habba tailaari — preparing for a celebration in Kannada","pattern":"X habbaake tailaari maaduttiddeeni = I am preparing for X festival. Naanu X biTTiddeeni = I have already done X (biTTiddeeni = have done it ahead of time). Nimantrana kodi = give invitations. Obbattu/sweets maadu = make sweets. Habba tayaaraadi = get ready for the festival. Huttida naaLu = birthday.","explanation":"Celebration vocabulary in Kannada: habba (festival/celebration), huttida naaLu (birthday), samaaraambha (celebration/event), tailaari (preparation). Preparing: tailaari maaduttiddeeni (I am preparing), ready maaduttiddeeni (I am getting ready), arrange maaduttiddeeni (I am arranging). Guest: atithi/ottige bande manushyaru (guests/visitors). Cook: oota maadbeku (need to cook food), sweets maadbeku (need to make sweets). Decorate: decorate maadabeku (need to decorate). Invite: nimantrana koDabeku / amantraNe koDabeku. Present/gift: present/gift tooguttini (I will bring a present). The biTTiddeeni structure: verb + biTTiddeeni = have already done (expressing completed preparatory action).","examples":[{"sentence":"Naanu already nimantrana kaTTabiTTiddeeni, inja decorate maaduttiddeeni.","english":"I have already sent the invitations, today I am decorating."},{"sentence":"Birthday party alli cake, sweets haagu kaapi teeTalaari maadibeku.","english":"For the birthday party we need to prepare cake, sweets and coffee."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"huttida naaLu means?","options":["birthday (lit. born day)","festival","celebration","holiday"],"correctAnswer":"birthday (lit. born day)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My birthday is tomorrow, I have already given invitations to my friends.","options":["Naanna birthday naale ide, naanu nanna mitrara nimantrana kodi friends ge biTTiddeeni.","Naanna birthday inja ide, naanu nanna mitrara nimantrana kodi friends ge biTTiddeeni.","Naanna birthday naale ide, naanu nimma mitrara nimantrana kodi friends ge biTTiddeeni.","Naanna birthday naale ide, avanu nanna mitrara nimantrana kodi friends ge biTTidaane."],"correctAnswer":"Naanna birthday naale ide, naanu nanna mitrara nimantrana kodi friends ge biTTiddeeni."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ugaadi habbaake naanu obbattu maadabeku — amma naakke ___ heLidaaLe.","options":["recipe","nimantrana","tailaari","samaaraambha"],"correctAnswer":"recipe"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I have already sent the invitations, today I am decorating.","wordBankItems":["Naanu","already","nimantrana","kaTTabiTTiddeeni",",","inja","decorate","maaduttiddeeni","."],"correctAnswer":"Naanu already nimantrana kaTTabiTTiddeeni , inja decorate maaduttiddeeni ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"tailaari means?","options":["preparation/readying","celebration","event","arrangement"],"correctAnswer":"preparation/readying"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000059',1,'APPROVED','PUBLISHED',
'{"objectives":["Learn and understand common Kannada proverbs","Use a proverb in context","Understand the cultural wisdom behind Kannada proverbs"],"explanation":{"intro":"Common Kannada proverbs and idioms covers a selection of famous Kannada gaadegaLu (proverbs) — their meaning, usage, and cultural context.","culturalNote":"Kannada proverbs (gaadegaLu): Kannada has an extremely rich proverb tradition — thousands of recorded gaadegaLu (literally ''proverb utterances'' — gaade = proverb, gaLu = plural). They encode ancient wisdom, humor, and social values. Key proverbs to know: (1) ''Kai keTTaare, kaLLa baDuttaare'' — if you become dependent (fold your hands), thieves appear (don''t be idle/dependent). (2) ''Mane devaru mana devaru'' — the god of the home is the mind''s god (family/home happiness is paramount). (3) ''Aaeru maneyalli paaTu, aaeru ooru alli haaDu'' — seven songs in the house, seven songs in the village (everything is in its proper place). (4) ''KeLuva manujare, keLuva manujare'' — O listening man, O listening man (a call to wisdom). (5) ''NuDidu nooru, maadidu ondu'' — said a hundred things, done one (talk is easy, action is hard). (6) ''OLLeyavara sobahudu, keTTavarinda dooraviru'' — be with good people, stay away from bad ones."},"examples":[{"sentence":"Kannada gaade: NuDidu nooru, maadidu ondu — meaning: talking is easy, doing is hard.","english":"Kannada proverb: ''Said a hundred, done one'' — meaning: talking is easy, doing is hard."},{"sentence":"Nanna ajja heeLuttidru — OLLeyavara sobahudu, keTTavarinda dooraviru.","english":"My grandfather used to say — be with good people, stay away from bad ones."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can understand and use common Kannada proverbs in context."}}',
'{"items":[{"word":"gaade","translation":"proverb/saying","transliteration":"gaade","pronunciation":"GAA-de","example":"Kannada gaade"},{"word":"artha","translation":"meaning/sense","transliteration":"artha","pronunciation":"AR-tha","example":"ee gaade artha"},{"word":"buddhi","translation":"wisdom/intellect","transliteration":"buddhi","pronunciation":"BUD-dhi","example":"channa buddhi"},{"word":"heeLuttidru","translation":"used to say (past habitual — 3rd plural)","transliteration":"heeLuttidru","pronunciation":"hee-LUT-tidh-ru","example":"nanna ajja heeLuttidru"},{"word":"nambabeku","translation":"one should believe/trust","transliteration":"nambabeku","pronunciation":"NAM-ba-be-ku","example":"nambabeku"},{"word":"OLLeyavaru","translation":"good people (plural)","transliteration":"OLLeyavaru","pronunciation":"OL-le-ya-va-ru","example":"OLLeyavara sobahudu"}]}',
'{"title":"Kannada gaadegaLu — proverbs and their meanings","pattern":"Gaade: X — artha: Y = Proverb: X — meaning: Y. Nanna ajja/ajji heeLuttidru = my grandfather/grandmother used to say. Ee gaade nanna jivanakke sari agutte = this proverb fits my life. Using a proverb: (context), haage gaade heeLuttaare (as the proverb says — haage = like that). Proverb in conversation: X anta nambuttini, gaade heLidaage.","explanation":"Proverb vocabulary in Kannada: gaade (proverb — the word itself means ''a saying'' from ''to say''), artha (meaning), buddhi (wisdom), neethi (moral lesson). Format: situation + proverb as explanation. Example: avanu bari maatnaaDuttaane, maaduttilla — ''NuDidu nooru, maadidu ondu'' anta gaade ide (he only talks, doesn''t do — there is a proverb ''said a hundred, done one''). Wisdom culture: in Karnataka, elders quote proverbs to give advice and explain situations. A well-timed proverb from an elder is considered very respectful and wise. Collecting proverbs: ''Shatakalyaana'' (Basavanna''s vachanas — short wisdom poems from 12th century) — considered the greatest Kannada literary wisdom tradition.","examples":[{"sentence":"Avaru kashtapaDuttidaare aadare gaade heLuttaare — ''OLLeyavara sobahudu, keTTavarinda dooraviru.''","english":"They are struggling, but the proverb says — ''Be with good people, stay away from bad ones.''"},{"sentence":"Nanna amma heeLuttidaLe — NuDidu nooru, maadidu ondu — kaarya maadabeku anta.","english":"My mother used to say — ''Said a hundred, done one'' — meaning one must take action."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"gaade means?","options":["proverb/saying","story","lesson","phrase"],"correctAnswer":"proverb/saying"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Kannada proverb: ''Said a hundred, done one'' — meaning: talking is easy, doing is hard.","options":["Kannada gaade: NuDidu nooru, maadidu ondu — meaning: talking is easy, doing is hard.","Kannada gaade: OLLeyavara sobahudu — meaning: talking is easy, doing is hard.","Kannada gaade: NuDidu nooru, maadidu ondu — meaning: saying is easy, believing is hard.","Hindustani gaade: NuDidu nooru, maadidu ondu — meaning: talking is easy, doing is hard."],"correctAnswer":"Kannada gaade: NuDidu nooru, maadidu ondu — meaning: talking is easy, doing is hard."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nanna amma heeLuttidaLe — NuDidu nooru, maadidu ondu — ___ maadabeku anta.","options":["kaarya","maatu","gaade","buddhi"],"correctAnswer":"kaarya"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My grandfather used to say — Be with good people, stay away from bad ones.","wordBankItems":["Nanna","ajja","heeLuttidru","—","OLLeyavara","sobahudu",",","keTTavarinda","dooraviru","."],"correctAnswer":"Nanna ajja heeLuttidru — OLLeyavara sobahudu , keTTavarinda dooraviru ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"artha means?","options":["meaning/sense","wisdom","lesson","word"],"correctAnswer":"meaning/sense"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000005a',1,'APPROVED','PUBLISHED',
'{"objectives":["Complete the full A1 review for Kannada","Demonstrate all A1 skills in an integrated conversation","Prepare for the transition to A2"],"explanation":{"intro":"A1 Complete Review prepares you for A2 by consolidating all skills from the 89 A1 lessons into a comprehensive final review covering language, culture, and grammar.","culturalNote":"Congratulations on completing Kannada A1! You now know: 600+ vocabulary words in Roman transliteration, all major A1 grammar patterns (three tenses, negation, beku/beda, postpositions), cultural knowledge of Bengaluru, Mysuru, Hampi, Western Ghats, Karnataka cuisine (saaru, palya, bisi bele bath, filter kaapi), festivals (Dasara, Ugaadi, Sankranti), arts (Yakshagana, Dollu Kunitha), sports (cricket, RCB, Rahul Dravid), cinema (Sandalwood, KGF, Puneeth Rajkumar), history (Hoysala, Vijayanagara, Tipu Sultan, Mysore Wodeyars), social norms (formal/informal register, invitation etiquette, proverbs). You can hold basic conversations with Kannadigas on everyday topics. A2 will take you further: complex sentences, reported speech, conditional sentences, more cultural depth, richer vocabulary. Ondu kaDe ondhu bageyindaa baruthiruva — from one side, you are coming a long way! A2 ge swaagata!"},"examples":[{"sentence":"Namaskara! Naanu A1 Kannada poorthi maadide. Karnataka, nimage namaskaara!","english":"Hello! I have completed A1 Kannada. Karnataka, I greet you!"},{"sentence":"A2 alli hecchaagi kalivona — Kannada thumba channa bhaashe!","english":"Let''s learn more in A2 — Kannada is a very beautiful language!"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":20,"canDo":"I have completed all 90 A1 Kannada lessons and am ready for A2!"}}',
'{"items":[{"word":"bhaashe","translation":"language","transliteration":"bhaashe","pronunciation":"BHAA-she","example":"Kannada bhaashe"},{"word":"poorthi maadide","translation":"I have completed (completed action)","transliteration":"poorthi maadide","pronunciation":"POOR-thi MAA-di-de","example":"A1 poorthi maadide"},{"word":"swaagata","translation":"welcome","transliteration":"swaagata","pronunciation":"SWA-ga-ta","example":"A2 ge swaagata"},{"word":"hecchaagi","translation":"more/further","transliteration":"hecchaagi","pronunciation":"HECH-chaa-gi","example":"hecchaagi kalivona"},{"word":"adbhuta","translation":"wonderful/amazing","transliteration":"adbhuta","pronunciation":"AD-bhu-ta","example":"adbhuta anubhava"},{"word":"abhimaana","translation":"pride/love/affection (for Karnataka)","transliteration":"abhimaana","pronunciation":"ab-hi-MAA-na","example":"Karnataka abhimaana"}]}',
'{"title":"A1 poorthi — complete A1 review and A2 preparation","pattern":"X poorthi maadide = I have completed X. A2 ge swaagata = welcome to A2! Hecchaagi kalivona = let''s learn more. Ee bhaashe channa = this language is beautiful. Abhimaana: Kannada bhaashe bagge naakke thumba abhimaana ide (I have a lot of love/pride for the Kannada language). All key sentences reviewed: Namaskara, naanu X iddini, hege iddiri, naakke beku, eshtu aagutte, dayavittu, dhanyavadagalu.","explanation":"Complete A1 review — all major patterns: (1) Greeting: Namaskara! Hege iddiri? Channaagi iddini. (2) Introduction: Naanu X, naanu Y inda. (3) Numbers: ondu to crore. (4) Time: gante, beLigge, raatri. (5) Shopping: eshtu aagutte? kodi. (6) Transport: X alli hoguttini. (7) Directions: nera/bala/yele, hattira. (8) Health: naakke novu ide. (9) Work: naanu X alli kaela maaduttini. (10) Hobbies: naakke X maaduvudu ishtavagutte. (11) Weather: varshakaala/beshige/chaleegaala. (12) Comparison: X ginta Y channa. (13) Feelings: naakke santosha/dukha/chintana aagutte. (14) Planning: hogona/naale hoguttini. (15) Farewell: mattaadi banni, nodu kottu. A2 preview: reported speech (avaru heLidaare ki = they said that), conditional (aadare = if), more complex comparisons.","examples":[{"sentence":"Nanu A1 Kannada kalijukoNDe, adbhuta anubhava — idu naanna Karnataka yaatra shuru!","english":"I have learned A1 Kannada, amazing experience — this is the start of my Karnataka journey!"},{"sentence":"Naanu Kannada bhaashe bagge thumba abhimaana baaLuttini — A2 ge hogona!","english":"I nurture a lot of pride for the Kannada language — let''s go to A2!"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"bhaashe means?","options":["language","culture","literature","tradition"],"correctAnswer":"language"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Hello! I have completed A1 Kannada. Karnataka, I greet you!","options":["Namaskara! Naanu A1 Kannada poorthi maadide. Karnataka, nimage namaskaara!","Namaskara! Naanu A2 Kannada poorthi maadide. Karnataka, nimage namaskaara!","Namaskara! Avanu A1 Kannada poorthi maadidaane. Karnataka, nimage namaskaara!","Namaskara! Naanu A1 Kannada poorthi maadide. Bengaluru, nimage namaskaara!"],"correctAnswer":"Namaskara! Naanu A1 Kannada poorthi maadide. Karnataka, nimage namaskaara!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu Kannada bhaashe bagge thumba ___ baaLuttini — A2 ge hogona!","options":["abhimaana","chintana","santosha","ishtavagutte"],"correctAnswer":"abhimaana"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Let''s learn more in A2 — Kannada is a very beautiful language!","wordBankItems":["A2","alli","hecchaagi","kalivona","—","Kannada","thumba","channa","bhaashe","!"],"correctAnswer":"A2 alli hecchaagi kalivona — Kannada thumba channa bhaashe !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"adbhuta means?","options":["wonderful/amazing","beautiful","important","great"],"correctAnswer":"wonderful/amazing"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

